<script setup>
import { useRouter } from 'vue-router'; import Button from 'primevue/button'; import { storeToRefs } from 'pinia'; import WeatherCard from '../components/WeatherCard.vue'; import { useWeatherStore } from '../stores/weatherStore'
const store=useWeatherStore(); const router=useRouter(); const {favoriteCities,selectedCityId}=storeToRefs(store)
const detail=(city)=>router.push({name:'weather-detail',params:{cityId:city.id}})
</script>
<template><main class="sub-page"><header><p>YOUR COLLECTION</p><h1>즐겨찾는 하늘</h1><span>{{ favoriteCities.length }}개 도시를 저장했습니다.</span></header><section v-if="favoriteCities.length" class="cards"><WeatherCard v-for="city in favoriteCities" :key="city.id" :city="city" is-favorite :selected="selectedCityId===city.id" @select-card="store.selectCity($event.id)" @click-detail="detail" @toggle-favorite="store.toggleFavorite" @open-context-menu="(_, menuCity) => detail(menuCity)" /></section><section v-else class="empty"><span>☆</span><h2>아직 즐겨찾는 도시가 없습니다.</h2><p>날씨 카드의 별 버튼이나 <kbd>F</kbd> 단축키로 추가해보세요.</p><Button label="날씨 둘러보기" @click="router.push('/')" /></section></main></template>
<style scoped>.sub-page{width:min(1080px,100%);min-height:calc(100vh - 70px);margin:auto;padding:60px 24px}.sub-page header{margin-bottom:30px}.sub-page header p{margin:0;color:var(--primary-700);font-size:10px;font-weight:700;letter-spacing:1.4px}.sub-page h1{margin:8px 0;color:var(--primary-900);font-size:42px;font-weight:700;letter-spacing:-1.4px}.sub-page header span{color:#3b5780}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.empty{padding:70px 20px;text-align:center;background:#fff;border:1px dashed var(--grey-200);border-radius:12px}.empty>span{font-size:48px}.empty p{margin-bottom:25px;color:#3b5780}@media(max-width:800px){.cards{grid-template-columns:repeat(2,1fr)}}@media(max-width:550px){.cards{grid-template-columns:1fr}}</style>
